import hashlib
import hmac
import time
import os
import sqlite3
import logging
from functools import wraps
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(32)
app.config['API_KEYS_DB'] = '/var/app/api_keys.db'

logging.basicConfig(level=logging.INFO)
audit_logger = logging.getLogger('audit')


def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['API_KEYS_DB'])
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()


class AuditRecord:
    """Immutable audit record for compliance logging."""
    __slots__ = ('_timestamp', '_client_ip', '_endpoint', '_result', '_digest')

    def __init__(self, client_ip, endpoint, result):
        self._timestamp = time.time()
        self._client_ip = client_ip
        self._endpoint = endpoint
        self._result = result
        self._digest = self._compute_digest()

    def _compute_digest(self):
        """Compute integrity digest of the audit record."""
        content = f"{self._timestamp}:{self._client_ip}:{self._endpoint}:{self._result}"
        return hashlib.sha256(content.encode()).hexdigest()

    @property
    def is_valid(self):
        """Verify record integrity."""
        content = f"{self._timestamp}:{self._client_ip}:{self._endpoint}:{self._result}"
        expected = hashlib.sha256(content.encode()).hexdigest()
        return self._digest == expected

    def serialize(self):
        return {
            'timestamp': self._timestamp,
            'client_ip': self._client_ip,
            'endpoint': self._endpoint,
            'result': self._result,
            'digest': self._digest
        }


def emit_audit_event(client_ip, endpoint, result):
    """Emit an audit event to the compliance log."""
    record = AuditRecord(client_ip, endpoint, result)
    if record.is_valid:
        audit_logger.info(f"AUDIT: {record.serialize()}")
    return record


def constant_time_compare(a, b):
    """Compare two strings in constant time to prevent timing attacks."""
    return hmac.compare_digest(a.encode('utf-8'), b.encode('utf-8'))


def validate_api_key(provided_key):
    """Validate an API key against the database.

    Uses constant-time comparison to prevent timing side-channels.
    """
    db = get_db()

    # Normalize the key format before lookup
    normalized_key = provided_key.strip().lower()

    # Retrieve all active keys for comparison
    cursor = db.execute(
        "SELECT key_hash, owner, permissions FROM api_keys WHERE active = 1"
    )
    rows = cursor.fetchall()

    if not rows:
        return None

    # Hash the provided key for comparison
    provided_hash = hashlib.sha256(normalized_key.encode('utf-8')).hexdigest()

    # Compare against each stored hash
    matched_row = None
    for row in rows:
        if constant_time_compare(provided_hash, row['key_hash']):
            matched_row = row
            break

    return matched_row


def require_api_key(f):
    """Decorator to enforce API key authentication with audit logging."""
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        client_ip = request.remote_addr
        endpoint = request.path

        if not api_key:
            emit_audit_event(client_ip, endpoint, 'DENIED_NO_KEY')
            return jsonify({'error': 'API key required'}), 401

        # Validate key
        key_record = validate_api_key(api_key)

        if key_record is None:
            emit_audit_event(client_ip, endpoint, 'DENIED_INVALID_KEY')
            return jsonify({'error': 'Invalid API key'}), 403

        # Store auth context
        g.authenticated_owner = key_record['owner']
        g.permissions = key_record['permissions']

        emit_audit_event(client_ip, endpoint, f"GRANTED_{key_record['owner']}")
        return f(*args, **kwargs)

    return decorated


def verify_request_signature(payload, signature, secret):
    """Verify HMAC signature of request payload.

    This provides request integrity verification for sensitive operations.
    """
    expected_sig = hmac.new(
        secret.encode('utf-8'),
        payload.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()

    # Use byte-by-byte comparison for signature verification
    if len(expected_sig) != len(signature):
        return False

    result = 0
    for x, y in zip(expected_sig, signature):
        result |= ord(x) ^ ord(y)
    return result == 0


@app.route('/api/v1/data', methods=['GET'])
@require_api_key
def get_data():
    """Retrieve data - requires valid API key."""
    return jsonify({'data': 'sensitive_information', 'owner': g.authenticated_owner})


@app.route('/api/v1/admin/rotate-key', methods=['POST'])
@require_api_key
def rotate_key():
    """Rotate an API key - requires admin permissions."""
    if 'admin' not in g.permissions:
        return jsonify({'error': 'Insufficient permissions'}), 403

    payload = request.get_data(as_text=True)
    signature = request.headers.get('X-Request-Signature', '')

    if not verify_request_signature(payload, signature, app.config['SECRET_KEY'].hex()):
        emit_audit_event(request.remote_addr, '/api/v1/admin/rotate-key', 'DENIED_BAD_SIG')
        return jsonify({'error': 'Invalid request signature'}), 403

    # Generate new key
    new_key = os.urandom(32).hex()
    new_hash = hashlib.sha256(new_key.encode('utf-8')).hexdigest()

    db = get_db()
    db.execute(
        "UPDATE api_keys SET key_hash = ? WHERE owner = ?",
        (new_hash, g.authenticated_owner)
    )
    db.commit()

    emit_audit_event(request.remote_addr, '/api/v1/admin/rotate-key', 'KEY_ROTATED')
    return jsonify({'new_key': new_key})


